  run_in_dir src/frontend uv run --frozen --no-sync ruff check
  run_in_dir src/frontend uv run --frozen --no-sync djlint --profile=jinja --check frontend/templates
  run_in_dir src/frontend uv run --frozen --no-sync pytest
}

